SELECT COALESCE(MAX(report_version_no), 0) + 1
FROM acc_acceptance_report_version
WHERE tenant_id = #{query.tenantId}
  AND acceptance_id = #{query.acceptanceId}
  AND deleted = b'0'

SELECT *
FROM acc_acceptance_report_version
WHERE tenant_id = #{query.tenantId}
  AND acceptance_id = #{query.acceptanceId}
  AND id = #{query.reportVersionId}
  AND deleted = b'0'
FOR UPDATE
